import urllib
from bs4 import BeautifulSoup

logger = logging.getLogger(__name__)
WURSTBALL_RE = re.compile(r"^https?://(www\.)?wurstball\.de/[0-9]+/")


def default_image_handler(image_url, root_url):
    return urllib.request.urlopen(image_url)


def wurstball_image_handler(image_url, root_url):
    if not WURSTBALL_RE.match(root_url):
        return None

    response = urllib.request.urlopen(image_url)
    mime_type = response.getheader("Content-Type")

    return {"mime_type": mime_type, "data": response.read()}

