from chainer import cuda
from chainer import function
from chainer.utils import type_check

import unittest


class Copy(function.Function):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_type_forward(self, in_type):
        type_check.expect(in_type.size() == 1)

    def check_type_backward(self, in_types, out_types):
        type_check.expect(out_types.size() == 1)
        type_check.expect(in_types[0].dtype.kind == \
            out_types[0].dtype.kind)
        type_check.expect(in_types[0].reshape(-1).shape == \
            out_types[0].reshape(-1).shape)

    def forward_cpu(self, x):
        return x[0].copy(),

    def forward_gpu(self, x):
        return cuda.copy(x[0], out_device=self.out_device),

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

    def backward_gpu(self, x, gy):
        return cuda.copy(gy[0], out_device=cuda.get_device(x[0])),


def copy(x, dst):
    """Copies the input variable onto the specified device.

    This function copies the array of input variable onto the device specified
    by ``dst`` if the original array is on GPU, and otherwise just copies the
    array within host memory.

    Args:
        x (~chainer.Variable): Variable to be copied.
        dst: Target device specifier.

    Returns:
        ~chainer.Variable: Output variable.

    """
    return Copy(dst)(x)


class CopyTest(unittest.TestCase):

    def setUp(self):
        self.x = chainer.Variable(cuda.cupy.arange(12).astype(numpy.float32)
                                  .reshape(2, 3, 4))

    def check_forward(self, xp):
        z = copy(xp.copy(self.x), None)
        self.assertEqual(z.device, self.x.device)
        self.assertEqual(z.data, self.x.data)

    def check_backward(self, xp):
        z = copy(self.x, None)
        z.grad_var = chainer.Variable(xp.ones(2, 3, 4).astype(numpy.float32))
        z.backward()
        self.assertEqual(z.xp, np)
        self.assertTrue((self.x.grad == 0).all())

    def test_forward_cpu(self):
        self.check_forward(np)

    @unittest.with_requires('chainer-cuda')
    def test_forward_gpu(self):
        self.check_forward(cuda.cupy)

    @unittest.with_requires('chainer-cuda')
    def test_backward_cpu(self):
        self.check_backward(np)

    @unittest.with_requires('chainer-cuda')
    def test_backward_gpu(self):
        self.check_backward(cuda.cupy)


